```java
// Bad example: Vulnerable to SQL injection due to dynamic query construction
public boolean authenticate(String username, String password) {
    Connection conn = null;
    try {
        conn = DriverManager.getConnection("jdbc:mysql://localhost/test");
        Statement stmt = conn.createStatement();
        // Vulnerable: User input concatenated directly into SQL query
        String query = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
        ResultSet rs = stmt.executeQuery(query);
        return rs.next();
    } catch (SQLException e) {
        e.printStackTrace();
        return false;
    }
}
```

***
```java
// Good example: Uses PreparedStatement to prevent SQL injection
public boolean authenticateSecure(String username, String password) {
    Connection conn = null;
    try {
        conn = DriverManager.getConnection("jdbc:mysql://localhost/test");
        // Secure: Parameterized query prevents SQL injection
        String query = "SELECT * FROM users WHERE username=? AND password=?";
        PreparedStatement stmt = conn.prepareStatement(query);
        stmt.setString(1, username); // Safely sets parameters
        stmt.setString(2, password);
        ResultSet rs = stmt.executeQuery();
        return rs.next();
    } catch (SQLException e) {
        e.printStackTrace();
        return false;
    }
}
```

